sp_BuscarTokenReset	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_BuscarTokenReset`(\n\n    IN p_token VARCHAR(200)\n\n)\nBEGIN\n\n    SELECT T.idToken, T.idUsuario, T.token, T.dthExpiracao, T.fUsado\n\n    FROM TokenResetSenha T\n\n    WHERE T.token        = p_token\n\n      AND T.fUsado       = 0\n\n      AND T.dthExpiracao > NOW();\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
